// Photography inquiry follow-up — what is due today.
// SELF-HEALING: keyed off "Touches" already sent + days since last contact,
// not off exact day numbers. A day nobody acts is a nag repeated, never a touch lost.
//
// Sheet columns: Name | Partner | Email | Phone | Event Date | Track | Stage |
//                Last Contact | Touches | Replied | Subject Line | Value | Notes
const today = new Date(); today.setHours(0,0,0,0);
const days = (a,b) => Math.round((a-b)/86400000);
const parseDate = (s) => { if(!s) return null; const d=new Date(s); return isNaN(d)?null:(d.setHours(0,0,0,0),d); };
const MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];
const pretty = (d, raw) => d ? `${d.getDate()} ${MONTHS[d.getMonth()]} ${d.getFullYear()}` : (raw || 'your date');

const out = [];

for (const item of $input.all()) {
  const r = item.json;
  const name = (r['Name']||'').trim();
  if (!name) continue;

  const stage   = (r['Stage']||'').toLowerCase().trim();
  const replied = (r['Replied']||'').toLowerCase().trim();

  // Stop rules.
  if (replied === 'yes') continue;
  if (['booked','closed','lost','flagged','done'].includes(stage)) continue;

  const last = parseDate(r['Last Contact']);
  if (!last) continue;
  const gap = days(today, last);
  if (gap < 1) continue;

  const eventDate   = parseDate(r['Event Date']);
  const daysToEvent = eventDate ? days(eventDate, today) : 999;
  const notes       = (r['Notes']||'').toLowerCase();

  // Event already passed and still not booked: it is over.
  if (eventDate && daysToEvent < 0) continue;

  let track = (r['Track']||'').toUpperCase().trim();
  if (!['A','B','C'].includes(track)) {
    if (stage === 'awaiting-payment') track = 'C';
    else if (daysToEvent <= 21 || notes.includes('travel')) track = 'B';
    else track = 'A';
  }

  const sent = parseInt(r['Touches']||'0', 10) || 0;

  // [minimum gap in days before this touch, touch name] indexed by touches already sent.
  const ladder = {
    A: [[2,'email-1'], [3,'whatsapp'], [4,'email-2'], [5,'closeout']],
    B: [[1,'whatsapp'], [1,'CALL'],    [2,'closeout']],
    C: [[1,'CALL'],     [1,'deadline']],
  }[track];

  if (sent >= ladder.length) continue;          // cadence exhausted, nothing more
  const [minGap, touch] = ladder[sent];
  if (gap < minGap) continue;                   // not due yet

  const first   = name.split(' ')[0];
  const partner = (r['Partner']||'').trim();
  const who     = partner ? `${name} and ${partner}` : name;
  const evt     = pretty(eventDate, r['Event Date']);
  const subject = (r['Subject Line']||'').trim();
  const overdue = gap - minGap;

  const T = {
    'email-1': { channel:'EMAIL — reply in the SAME thread, SAME subject line',
      text:`Hi ${first},\n\nMaking sure this reached you, since email has a habit of burying things.\n\n${evt} is still open and I would like to hold it for you.\n\nShall I?\n\nWarmly,\nHadi` },
    'whatsapp': { channel:`WHATSAPP to ${r['Phone']||'(no number on file)'}`,
      text: track==='B'
        ? `Hi ${first}, following up on ${evt}. It is close now so I wanted to make sure you had what you needed. The slot is still yours if you want it. Shall I hold it?`
        : `Hi ${first}, Hadi here from Hadi Photography London. I wrote to you about ${evt} earlier in the week, worth a look in spam if it is not in your inbox. The date is still open. Would you like me to hold it?` },
    'email-2': { channel:'EMAIL — same thread. Lead with something useful, not a chase.',
      text:`Hi ${first},\n\nA week disappears quickly when you are planning something, so no need to apologise for the quiet.\n\n[ONE USEFUL THING: a note on the light at their time of year, a thought about their location, or a link to the relevant guide]\n\n${evt} is still free. Shall I hold it for you?\n\nWarmly,\nHadi` },
    'CALL': { channel:`*** PHONE CALL *** ${r['Phone']||'(no number on file)'} — not an email`,
      text: track==='C'
        ? `They have already said yes. Something practical is in the way: the link did not open, a card was declined, they are waiting on a partner, wrong timezone. Ninety seconds on the phone solves all of it. Email solves none of it.\n\n"Hi ${first}, Hadi here. Just checking the booking link came through alright?"`
        : `Thirty seconds.\n\n"Hi ${first}, Hadi here, the photographer. Just checking you got my email about ${evt}. Did you want to go ahead?"\n\nVoicemail: leave one, then WhatsApp to say you called.` },
    'deadline': { channel:'EMAIL — same thread. A real deadline, honestly stated.',
      text:`Hi ${first},\n\nI have not managed to reach you and the booking has not come through, so ${evt} is still unheld.\n\nI will keep it for you until [time tomorrow], then release it back to the diary.\n\nWould you still like it?\n\nWarmly,\nHadi` },
    'closeout': { channel:'EMAIL — same thread. Final touch. Nothing after this.',
      text: track==='B'
        ? `Hi ${first}, I am releasing ${evt} since it is nearly here and I have not managed to reach you. If something changes, message me any time. Enjoy London either way.`
        : `Hi ${first},\n\nI am going to close your enquiry so it stops sitting in your inbox, and release ${evt} back to the diary. Nothing needed from you.\n\nIf your plans firm up later, write to me and I will tell you honestly whether the date is still there. I would be glad to hear from you either way.\n\nWishing you both a wonderful year.\n\nWarmly,\nHadi` },
  }[touch];

  out.push({ json: {
    who, first, track, touch, gap, overdue, stage, sent,
    channel: T.channel, text: T.text,
    email: r['Email']||'', phone: r['Phone']||'',
    subject: subject ? `Re: ${subject}` : '(use the original subject line)',
    value: r['Value']||'', eventDate: evt, daysToEvent,
    urgent: (touch === 'CALL' || track === 'C' || overdue >= 2),
  }});
}

return out;

const items = $input.all().map(i => i.json);
if (items.length === 0) return [{ json: { skip: true } }];

items.sort((a,b) => (b.urgent===true)-(a.urgent===true) || b.overdue-a.overdue);

const urgent = items.filter(i => i.urgent).length;
const subject = `Follow-ups due: ${urgent ? urgent + ' URGENT — ' : ''}${items.length} ${items.length===1?'person':'people'}`;

let body = `${items.length} follow-up${items.length===1?'':'s'} due today.\n`;
body += `Text is ready to send. Reply in the SAME email thread so the original resurfaces.\n`;
body += `\n${'='.repeat(62)}\n`;

for (const i of items) {
  body += `\n${i.urgent ? '>>> URGENT <<<  ' : ''}${i.who.toUpperCase()}\n`;
  body += `Track ${i.track} · touch ${i.sent+1} · ${i.gap} day${i.gap===1?'':'s'} since last contact`;
  body += i.overdue > 0 ? `  (${i.overdue} day${i.overdue===1?'':'s'} OVERDUE)\n` : `\n`;
  body += `${i.stage}${i.value ? ' · ' + i.value : ''} · event ${i.eventDate}`;
  body += i.daysToEvent < 999 ? ` (${i.daysToEvent} days away)\n` : `\n`;
  body += `${i.email}${i.phone ? '  |  ' + i.phone : ''}\n`;
  body += `Subject: ${i.subject}\n\n${i.channel}\n`;
  body += `${'-'.repeat(62)}\n${i.text}\n${'-'.repeat(62)}\n\n${'='.repeat(62)}\n`;
}

body += `\nAfter you send: put today's date in Last Contact and add 1 to Touches.\n`;
body += `If they reply: set Replied to yes. That stops everything.\n`;
body += `\nUntil the sheet is updated this email repeats daily. That is deliberate.\n`;
body += `\nPlaybook: .claude/templates/inquiry-follow-up-playbook.md\n`;
return [{ json: { subject, body, count: items.length } }];
